contract InvMutTest {
    C c;
    uint256 ownerBefore;
    uint256 cBefore;
    uint256 ownerAfter;
    uint256 cAfter;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "not enough balance");

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        ownerBefore = owner.balance;
        cBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        cAfter = address(c).balance;
        ownerAfter = owner.balance;

        assert(
            (reverted && cAfter == cBefore && ownerAfter == ownerBefore) ||
            (!reverted && cAfter <= cBefore && ownerAfter <= ownerBefore + cBefore + amount)
        );
    }

    receive() external payable {}
}

