    B c;
    uint256 ownerBefore;
    uint256 cBefore;
    uint256 ownerAfter;
    uint256 cAfter;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        ownerBefore = owner.balance;
        cBefore = address(c).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        cAfter = address(c).balance;
        ownerAfter = owner.balance;
        assertTrue((reverted && cAfter == cBefore && ownerAfter == ownerBefore) ||
            (!reverted && cAfter <= cBefore && ownerAfter <= ownerBefore + cBefore + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

